import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_forward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    const float subVal,
    const float mulVal,
    float* __restrict__ out,
    const int batch_size,
    const int in_features,
    const int out_features
) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < batch_size && col < out_features) {
        float val = 0;
        for (int k = 0; k < in_features; k++) {
            val += x[row * in_features + k] * w[col * in_features + k];
        }
        val += b[col];
        val -= subVal;
        val *= mulVal;
        if (val < 0) {
            val = 0;
        }
        out[row * out_features + col] = val;
    }
}

torch::Tensor fused_forward_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b,
    float subVal,
    float mulVal
) {
    auto batch_size = x.size(0);
    auto in_features = x.size(1);
    auto out_features = w.size(0);

    auto out = torch::zeros({batch_size, out_features}, x.options());

    dim3 block(16, 16);
    dim3 grid((batch_size + block.x - 1) / block.x,
              (out_features + block.y - 1) / block.y);

    fused_forward_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        subVal,
        mulVal,
        out.data_ptr<float>(),
        batch_size,
        in_features,
        out_features
    );

    return out;
}
"""

fused_cpp_source = r"""
torch::Tensor fused_forward_cuda(
    torch::Tensor x,
    torch::Tensor w,
    torch::Tensor b,
    float subVal,
    float mulVal
);
"""

fused_op = load_inline(
    name="fused_op",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_forward_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, subtract_value, multiply_value):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))
        self.subVal = subtract_value
        self.mulVal = multiply_value

    def forward(self, x):
        return fused_op.fused_forward_cuda(x, self.weight, self.bias, self.subVal, self.mulVal)
